// AA2735 Window Atlas: headline points of interest along ORD-SMF and SMF-ORD.
// legs[] computed from cross-track distance to route.js waypoints (<=220 km; tall peaks/volcanoes/ranges <=320 km).
// Crossing items (kind "crossing") sit on the route line of the single leg they belong to.
window.POIS = [
 {"id":"sacramento","name":"Sacramento","kind":"city","lat":38.58,"lon":-121.49,"elevFt":30,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Gold Rush river town turned state capital","blurb":"Sacramento grew where the American River meets the Sacramento River, on flat ground built by floods carrying Sierra sediment. Levees and the Yolo Bypass now steer floodwater around the city. The valley floor here sits barely above sea level.","lookFor":"A grid of tree-lined streets with the green Capitol dome district beside the Sacramento River. The wide Yolo Bypass lies just west, often flooded silver in wet winters.","history":"John Sutter built his fort here in 1839, and the 1848 gold strike upriver turned it into a boomtown. The Central Pacific Railroad began building east from Sacramento in 1863.","nearby":["Sutter's Fort near downtown","Tower Bridge over the Sacramento River","Yolo Bypass to the west"],"fact":"Western end of the Pony Express in 1860","priority":2},
 {"id":"sacramento-valley-rice","name":"Sacramento Valley rice fields","kind":"plains","lat":39.1,"lon":-121.75,"extentKm":60,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Flooded paddies that mirror the sky","blurb":"The northern Central Valley holds dense clay soils that trap water, ideal for flooded rice. Fields are leveled with lasers and flooded in spring, then flooded again in winter to break down straw. Migrating ducks and geese use them as stand-in wetlands.","lookFor":"A patchwork of flat rectangles: mirror-bright in spring and winter, green in summer, golden-brown at harvest in September and October.","nearby":["Sutter Buttes rising from the fields","Feather River levees"],"fact":"California grows roughly 500,000 acres of rice","priority":3},
 {"id":"sutter-buttes","name":"Sutter Buttes","kind":"volcano","lat":39.206,"lon":-121.82,"elevFt":2122,"extentKm":16,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A ring of old volcano in the middle of the valley","blurb":"The Sutter Buttes are the eroded core of a volcano that pushed up through valley sediments about 1.6 million years ago. Lava domes form the jagged center, ringed by a moat and an outer rim of tilted sediment. Nothing else like it rises from the Central Valley floor.","lookFor":"A compact, circular knot of rugged hills standing alone in the flat valley, about 10 miles across, northwest of Sacramento. Green in winter and spring, tawny in summer.","history":"The Maidu and Patwin held the Buttes sacred. Frémont camped here in 1846 just before the Bear Flag Revolt.","fact":"Rises about 2,000 ft from a valley near sea level","era":"Pleistocene volcanic, ~1.6 Ma","priority":1},
 {"id":"folsom-lake","name":"Folsom Lake","kind":"reservoir","lat":38.72,"lon":-121.13,"legs":["ORD-SMF","SMF-ORD"],"tagline":"American River held behind Folsom Dam","blurb":"Folsom Dam, finished in 1956, backs up the North and South Forks of the American River in the Sierra foothills. Its level swings widely, exposing broad bathtub rings of granite sand in drought years.","lookFor":"A branching, two-armed lake east of Sacramento with pale sandy shores. In dry years the exposed banks look like a wide tan border.","history":"Drought in 2014 drained the lake enough to expose the Gold Rush town of Mormon Island, flooded since the 1950s.","fact":"Holds about 977,000 acre-feet when full","priority":2},
 {"id":"coloma","name":"Coloma (Sutter's Mill)","kind":"history","lat":38.8,"lon":-120.89,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Where the California Gold Rush began","blurb":"On the South Fork of the American River, James Marshall spotted gold flakes in the tailrace of Sutter's sawmill. The gold had weathered out of quartz veins in the Sierra foothills and collected in river gravels.","lookFor":"A narrow green river valley in the oak-covered foothills east of Folsom Lake. The town itself is tiny; look for the South Fork winding through.","history":"Marshall's find on January 24, 1848 set off the rush of 1849, drawing roughly 300,000 people to California within a few years.","fact":"Gold found January 24, 1848","priority":2},
 {"id":"yuba-englebright","name":"Yuba River & Englebright Lake","kind":"river","lat":39.24,"lon":-121.27,"line":[[-120.55,39.52],[-120.85,39.42],[-121.05,39.31],[-121.27,39.24],[-121.45,39.2],[-121.58,39.13]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"A river buried by Gold Rush mud","blurb":"Hydraulic miners blasted whole hillsides into the Yuba with water cannons, sending enough gravel downstream to raise riverbeds by many feet and bury farms. Englebright Dam was built in 1941 partly to trap that debris. Rounded cobble ridges left by dredges still line the lower river near Marysville.","lookFor":"A twisting, steep-walled canyon in the foothills feeding a narrow green reservoir, then a braided band of gray cobble mounds where the river leaves the hills.","history":"The 1884 Sawyer decision ended unrestricted hydraulic mining, one of the first environmental rulings in American law.","nearby":["Englebright Dam","Yuba Goldfields dredge tailings","Malakoff Diggins pit to the north"],"fact":"Sawyer decision of 1884 halted hydraulic mining","priority":2},
 {"id":"lake-oroville","name":"Lake Oroville","kind":"reservoir","lat":39.55,"lon":-121.45,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Behind the tallest dam in the United States","blurb":"Oroville Dam, an earthfill embankment on the Feather River, is about 770 ft tall. The reservoir floods several deep foothill canyons, giving it a sprawling, many-fingered shape.","lookFor":"A spidery reservoir with long arms reaching into the foothills north of the Sutter Buttes, often ringed with red-orange exposed banks.","history":"In February 2017 erosion of its spillways forced the evacuation of about 188,000 people downstream.","fact":"Dam about 770 ft tall","priority":3},
 {"id":"sierra-nevada","name":"Sierra Nevada","kind":"range","lat":39.2,"lon":-120.4,"extentKm":640,"line":[[-120.95,40.25],[-120.62,39.65],[-120.33,39.32],[-120.05,38.85],[-119.62,38.25],[-119.25,37.73],[-118.75,37.1],[-118.3,36.58],[-118.35,35.8]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"A tilted granite block 400 miles long","blurb":"The Sierra Nevada is a single giant block of granite tilted westward: a long gentle slope toward the Central Valley and a steep fault scarp on the east. Most of the granite cooled from magma chambers roughly 85 to 125 million years ago, deep beneath a chain of volcanoes. Glaciers later carved its passes and lake basins.","lookFor":"Forested ridges rising from golden foothills into bare gray granite and snowfields. On the east side the range drops abruptly toward the Nevada desert.","history":"The emigrant passes, the first transcontinental railroad and Interstate 80 all squeeze over the crest near Donner Pass.","nearby":["Donner Pass","Castle Peak","Lake Tahoe basin"],"fact":"About 400 miles long","era":"Mostly Cretaceous granite, ~125-85 Ma","priority":1},
 {"id":"donner-lake-pass","name":"Donner Lake & Donner Pass","kind":"history","lat":39.32,"lon":-120.29,"elevFt":7056,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Tragedy, then triumph, at the Sierra crest","blurb":"Donner Lake sits in a basin scoured by glaciers just below the granite crest. The pass above it is one of the lowest practical notches in the northern Sierra, so trails, rails and highways all converge here.","lookFor":"A small oval lake just west of Truckee with granite slabs and the I-80 grade climbing above its west end. Snowsheds and old rail grades scar the cliffs at the pass.","history":"The Donner Party was trapped here by snow in the winter of 1846-47. Twenty years later Chinese crews blasted the Central Pacific's Summit Tunnel through solid granite at the pass.","nearby":["Summit Tunnel and old railroad grade","Truckee to the east","Sugar Bowl ski area"],"fact":"Pass elevation 7,056 ft","priority":1},
 {"id":"castle-peak","name":"Castle Peak","kind":"peak","lat":39.3676,"lon":-120.3474,"elevFt":9103,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Volcanic battlements above Donner Summit","blurb":"Castle Peak is capped by dark volcanic rock that erodes into turret-like crags, unlike the smooth granite around it. It is the high point near Donner Summit and holds snow well into summer.","lookFor":"A dark, castle-shaped summit just north of I-80 at the crest, with a long ridge running north.","fact":"9,103 ft, the high point above Donner Summit","priority":2},
 {"id":"sierra-buttes","name":"Sierra Buttes","kind":"peak","lat":39.594,"lon":-120.639,"elevFt":8591,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Jagged crown with a lookout on top","blurb":"The Sierra Buttes are a serrated ridge of old volcanic rock above a string of glacial lakes. Their saw-tooth profile stands out from the rounder northern Sierra.","lookFor":"A sharp, jagged ridge north of the track with small glacial lakes (Lakes Basin) at its foot.","history":"Gold mines tunneled deep into the Buttes in the 1850s; Sierra City sits at their base.","nearby":["Lakes Basin to the north","Sierra City on the North Yuba"],"fact":"A fire lookout sits on the 8,591 ft summit","priority":2},
 {"id":"lake-tahoe","name":"Lake Tahoe","kind":"lake","lat":39.09,"lon":-120.04,"elevFt":6225,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A deep blue block dropped between faults","blurb":"Lake Tahoe fills a basin that dropped down between faults as the Sierra and Carson Range rose on either side. It is the second-deepest lake in the United States. Its water is so clear that its color reads as dark sapphire from the air.","lookFor":"A huge deep-blue oval ringed by forest and granite, with turquoise shallows at Emerald Bay on the southwest shore.","history":"The Washoe people summered at its shores for thousands of years. Comstock miners logged much of the basin for timber and fuel in the 1870s.","nearby":["Emerald Bay","Truckee River outlet at Tahoe City","Mount Rose to the northeast"],"fact":"1,645 ft deep","era":"Fault basin, ~2-3 Ma","priority":1},
 {"id":"lassen-peak","name":"Lassen Peak","kind":"volcano","lat":40.4882,"lon":-121.505,"elevFt":10457,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The volcano that erupted a century ago","blurb":"Lassen Peak is one of the largest lava dome volcanoes on Earth and the southernmost active volcano of the Cascades. Its eruptions from 1914 to 1917 sent mudflows down its slopes. Boiling springs and fumaroles still steam on its flanks.","lookFor":"A broad, snow-streaked peak far to the north, standing apart at the southern end of the Cascade chain.","history":"The large eruption of May 22, 1915 was photographed by local resident B.F. Loomis, giving scientists a rare record.","fact":"Last erupted 1914-1917","era":"Dacite dome, ~27,000 yrs","priority":1},
 {"id":"mount-shasta","name":"Mount Shasta","kind":"volcano","lat":41.409,"lon":-122.195,"elevFt":14179,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Snow-capped giant on the far northern horizon","blurb":"Mount Shasta is a stratovolcano built from several overlapping cones. It rises about 10,000 ft above its surroundings and holds glaciers year-round.","lookFor":"On a very clear day, a lone white cone on the far northern horizon. It is far away, so look for it only in crisp air.","fact":"14,179 ft","era":"Stratovolcano, active","priority":2},
 {"id":"reno","name":"Reno & the Truckee Meadows","kind":"city","lat":39.53,"lon":-119.81,"elevFt":4505,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The Biggest Little City in the World","blurb":"Reno spreads across the Truckee Meadows, a fault-bounded valley where the Truckee River leaves the Sierra. The river flows through downtown and on to Pyramid Lake.","lookFor":"A sprawling city in a desert valley at the foot of the Sierra, with casino towers downtown and the Truckee River threading east.","history":"Reno began as a Central Pacific railroad stop in 1868 and later became famous for quick divorces and gambling.","nearby":["Truckee River through downtown","Mount Rose to the southwest","Tahoe-Reno Industrial Center to the east"],"fact":"Elevation 4,505 ft","priority":2},
 {"id":"mount-rose","name":"Mount Rose","kind":"peak","lat":39.3437,"lon":-119.9177,"elevFt":10776,"legs":["ORD-SMF","SMF-ORD"],"tagline":"High point above the Truckee Meadows","blurb":"Mount Rose is the high point of the Carson Range, a spur of the Sierra between Lake Tahoe and Reno. Its upper slopes are volcanic rock over granite.","lookFor":"A bulky, often snowy summit between Reno and the north end of Lake Tahoe.","history":"James Church built a snow-survey station here in 1906 and pioneered modern snowpack measurement.","fact":"10,776 ft","priority":3},
 {"id":"virginia-city","name":"Virginia City & the Comstock Lode","kind":"mine","lat":39.31,"lon":-119.65,"elevFt":6150,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Silver bonanza on the side of a mountain","blurb":"The Comstock Lode was a rich vein of silver and gold deposited by hot fluids along a fault in old volcanic rock. Miners followed it more than 3,000 ft down, battling scalding water. Square-set timbering, invented here, kept the deep stopes from collapsing.","lookFor":"A small town clinging to the east face of the Virginia Range southeast of Reno, with pale mine dumps spilling down the slopes.","history":"The 1859 strike helped finance the Union during the Civil War and helped push Nevada to statehood in 1864. Mark Twain began writing under that name at the Territorial Enterprise here.","nearby":["Mine dumps on Mount Davidson","Gold Hill just south","Sutro Tunnel portal to the east"],"fact":"Sutro Tunnel, nearly 4 miles long, finished 1878","priority":2},
 {"id":"pyramid-lake","name":"Pyramid Lake","kind":"lake","lat":40,"lon":-119.55,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Turquoise remnant of an ice-age sea","blurb":"Pyramid Lake is one of the largest surviving pieces of ancient Lake Lahontan, fed only by the Truckee River. Calcium-rich spring water mixed with lake water to build tufa towers and mounds along its shores. Its water is slightly salty and has no outlet.","lookFor":"A long blue-green lake in bare desert hills north of Reno. Look for the pale pyramid-shaped tufa island near the east shore and Anaho Island in the middle.","history":"The lake lies within the Pyramid Lake Paiute Reservation. John C. Frémont named it in January 1844 for the pyramid-shaped tufa island.","nearby":["The Pyramid tufa island","Anaho Island pelican colony","The Needles tufa spires at the north end"],"fact":"Named by Frémont in January 1844","era":"Lahontan remnant, Pleistocene","priority":1},
 {"id":"black-rock-desert","name":"Black Rock Desert playa","kind":"saltflat","lat":40.9,"lon":-119.1,"extentKm":60,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Flattest, emptiest ground in North America","blurb":"The Black Rock playa is the dry floor of an arm of Lake Lahontan, smoothed by seasonal sheets of water and wind. It is so flat that a car can drive for miles in a straight line. The dark knob of Black Rock Point gave the desert its name.","lookFor":"A huge, smooth, pale tan or white expanse far to the north, often with a faint dust haze. In late summer you may spot the circular camp of Burning Man.","history":"The Applegate-Lassen emigrant trail crossed the playa from Black Rock Point in the 1840s. In 1997 the ThrustSSC car broke the sound barrier on its surface.","nearby":["Black Rock Point","Burning Man site (late summer)","Smoke Creek Desert to the south"],"fact":"763 mph land speed record, 1997","priority":1},
 {"id":"humboldt-sink","name":"Humboldt Sink","kind":"basin","lat":39.95,"lon":-118.62,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Where the Humboldt River simply ends","blurb":"The Humboldt River never reaches the sea. It spreads into marshes and a shallow lake bed south of Lovelock and evaporates. White alkali crusts mark where water stood.","lookFor":"A pale, cracked flat with patches of marsh green or standing water, south of Lovelock where the Humboldt River fades out.","history":"Emigrants on the California Trail rested here before facing the waterless Forty Mile Desert.","fact":"End of a 330-mile river","priority":2},
 {"id":"carson-sink","name":"Carson Sink & Lake Lahontan","kind":"basin","lat":39.8,"lon":-118.35,"extentKm":50,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Floor of a vanished inland sea","blurb":"The Carson Sink is the lowest basin of ancient Lake Lahontan, which filled much of western Nevada during the ice ages. Today it is a vast salt-and-mud playa that floods in wet years. Old shorelines appear as faint level lines on nearby hills.","lookFor":"A broad white-gray flat south of the track, sometimes holding a sheet of shallow water, with green Stillwater marshes on its south side.","nearby":["Stillwater marshes","Lahontan shorelines on the hills"],"fact":"Lake Lahontan once covered about 8,500 sq mi","era":"Pleistocene lake bed","priority":2},
 {"id":"forty-mile-desert","name":"Forty Mile Desert","kind":"history","lat":39.72,"lon":-118.85,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The deadliest stretch of the California Trail","blurb":"Between the Humboldt Sink and the Truckee and Carson rivers lay about 40 miles with no fresh water. The ground is sand and alkali flats left by Lake Lahontan.","lookFor":"Bare tan and white flats with low sand dunes between the Humboldt Sink and the green line of the Truckee River at Fernley.","history":"An 1850 count tallied about 953 graves and thousands of dead oxen, horses and mules along the crossing.","fact":"About 953 graves counted in 1850","priority":2},
 {"id":"humboldt-river","name":"Humboldt River","kind":"river","lat":40.65,"lon":-117,"line":[[-114.96,41.11],[-115.4,40.95],[-115.76,40.83],[-116.1,40.71],[-116.4,40.63],[-116.93,40.64],[-117.3,40.85],[-117.73,40.97],[-118.15,40.65],[-118.31,40.47],[-118.47,40.18],[-118.62,39.97]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"The emigrants' lifeline across Nevada","blurb":"The Humboldt flows west for about 330 miles across Nevada and ends in a desert sink. It cuts through ranges instead of going around them, following a corridor that early emigrants, the railroad and I-80 all used.","lookFor":"A thin, winding green ribbon with willows and hay meadows, tracked closely by I-80 and two rail lines across brown sagebrush country.","history":"Peter Skene Ogden's fur trappers reached it in 1828. Frémont named it for the naturalist Alexander von Humboldt.","nearby":["Palisade Canyon near Carlin","Rye Patch Reservoir","Humboldt Sink at the end"],"fact":"About 330 miles, never reaches the sea","priority":1},
 {"id":"battle-mountain","name":"Battle Mountain","kind":"city","lat":40.642,"lon":-116.934,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Mining town on the world's fastest bike road","blurb":"Battle Mountain sits on the Humboldt River among ranges rich in gold and copper deposits. Big open-pit mines lie in the hills to the south and west.","lookFor":"A small grid town on the Humboldt floodplain with terraced pit mines in the brown hills to the south.","history":"Each September, cyclists in streamlined pods race on State Route 305 here. In 2016 Todd Reichert reached about 89.6 mph in the Aerovelo Eta, a human-powered record.","fact":"Human-powered record of about 89.6 mph, 2016","priority":3},
 {"id":"carlin-trend","name":"Carlin Trend gold mines","kind":"mine","lat":40.88,"lon":-116.3,"line":[[-116.48,41.08],[-116.36,40.98],[-116.25,40.85],[-116.15,40.73],[-116.05,40.63]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Invisible gold, enormous pits","blurb":"Along a northwest-trending belt of faulted limestone, hot fluids deposited gold in grains too small to see. Mining these low-grade ores means moving huge volumes of rock, so the pits and waste dumps are enormous.","lookFor":"Terraced open pits, flat-topped waste dumps and leach pads in gray and tan, strung along the hills northwest of Carlin.","history":"Newmont's Carlin mine opened in 1965 after geologists recognized microscopic gold here, opening a new kind of gold deposit to the world.","nearby":["Goldstrike pits to the north","Gold Quarry pit near Carlin"],"fact":"Gold grains often under a micron across","priority":1},
 {"id":"elko","name":"Elko","kind":"city","lat":40.832,"lon":-115.763,"elevFt":5067,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Cowboy and Basque town below the Rubies","blurb":"Elko sits on the Humboldt River at the northwest foot of the Ruby Mountains. It serves the ranches and the gold mines of northern Nevada.","lookFor":"A town on the Humboldt floodplain with I-80 and the railroad running through, and the Ruby Mountains rising to the southeast.","history":"Elko was founded by the Central Pacific in 1868. It has hosted the National Cowboy Poetry Gathering since 1985 and has a deep Basque heritage.","fact":"Cowboy Poetry Gathering since 1985","priority":3},
 {"id":"ruby-mountains","name":"Ruby Mountains","kind":"range","lat":40.45,"lon":-115.45,"elevFt":11387,"extentKm":130,"line":[[-115.22,40.8],[-115.33,40.72],[-115.4754,40.6216],[-115.4,40.56],[-115.4,40.5],[-115.43,40.42],[-115.47,40.35],[-115.51,40.25],[-115.55,40.13],[-115.57,40.02]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Nevada's alpine island in the desert","blurb":"The Ruby Mountains are a metamorphic core complex: rock once buried 10 miles deep was stretched and lifted to the surface as the Great Basin pulled apart. Glaciers then carved cirques, U-shaped canyons and lake basins into the granite and marble. They catch far more snow than the surrounding desert.","lookFor":"A long north-south wall of high peaks with white snow streaks, cirques and gray rock south of Elko. The crest is sharp and glacier-bitten, unlike the rounded desert ranges around it.","history":"Early travelers found garnets in the streams and named the range for rubies. In 1846 the Hastings Cutoff, used by the Donner Party, followed Ruby Valley along the range's east foot.","nearby":["Ruby Dome, the highest summit","Lamoille Canyon on the northwest side","Ruby Valley along the east foot","Harrison Pass at the south"],"fact":"About 80 miles long, 10 wide","era":"Metamorphic core complex, uplifted ~30-20 Ma","priority":1},
 {"id":"ruby-dome","name":"Ruby Dome","kind":"peak","lat":40.6216,"lon":-115.4754,"elevFt":11387,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Crown of the Rubies","blurb":"Ruby Dome is the highest summit of the Ruby Mountains, built of metamorphic rock and granite exhumed from deep in the crust. Glacial cirques bite into its flanks.","lookFor":"The tallest, broad-shouldered summit near the north end of the Ruby crest, usually holding late snow.","fact":"11,387 ft","priority":2},
 {"id":"lamoille-canyon","name":"Lamoille Canyon","kind":"canyon","lat":40.64,"lon":-115.43,"line":[[-115.48,40.69],[-115.45,40.66],[-115.42,40.63],[-115.4,40.6],[-115.39,40.58]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"A textbook glacier-carved U","blurb":"Ice filled Lamoille Canyon during the ice ages and ground it into a broad U-shaped trough with hanging valleys on its sides. Moraines at its mouth mark where the glacier stopped.","lookFor":"A deep, straight canyon notching into the north end of the Rubies southeast of Elko, with cliffs and avalanche chutes on both walls.","fact":"Road climbs to about 8,800 ft","era":"Glacial trough, Pleistocene","priority":2},
 {"id":"east-humboldt-range","name":"East Humboldt Range","kind":"range","lat":40.98,"lon":-115.1,"elevFt":11311,"line":[[-115.2,40.8],[-115.15,40.88],[-115.1,40.95],[-115.08,41.02],[-115.02,41.1],[-114.98,41.15]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Northern twin of the Rubies, above Wells","blurb":"The East Humboldt Range is the northern continuation of the same uplifted core complex as the Rubies, separated by Secret Pass. Its west face is steep and cut by glacial cirques.","lookFor":"A rugged, snow-streaked range just south of Wells, rising sharply from the Humboldt headwaters.","nearby":["Hole in the Mountain Peak","Angel Lake cirque above Wells","Secret Pass separating it from the Rubies"],"fact":"Hole in the Mountain Peak, 11,311 ft","priority":2},
 {"id":"ruby-valley","name":"Ruby Valley & Ruby Lake NWR","kind":"lake","lat":40.2,"lon":-115.47,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Spring-fed marsh at the foot of the Rubies","blurb":"Ruby Valley lies along the east foot of the Ruby Mountains. At its south end, Ruby Lake National Wildlife Refuge is a marsh fed by springs from snowmelt that soaked into the range.","lookFor":"Green and blue marshland with open water channels in a long valley east of the Ruby crest, in sharp contrast to the brown sagebrush.","history":"The 1863 Treaty of Ruby Valley between the U.S. and the Western Shoshone is still at the center of a land-rights dispute.","fact":"Fed by more than 200 springs","priority":2},
 {"id":"jarbidge","name":"Jarbidge Mountains & Wilderness","kind":"range","lat":41.81,"lon":-115.38,"elevFt":10839,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Remote high country near the Idaho line","blurb":"The Jarbidge Mountains are a cluster of eight peaks over 10,000 ft built mostly of volcanic rock. Deep canyons drain north toward the Snake River.","lookFor":"A compact group of high, snowy peaks far to the north of Elko, near the Idaho border.","history":"Nevada's first designated wilderness (1964). The 1916 Jarbidge holdup is often called the last stagecoach robbery in the U.S.","nearby":["Matterhorn Peak","Jarbidge town in its canyon"],"fact":"Matterhorn Peak, 10,839 ft","priority":2},
 {"id":"pequop-mountains","name":"Pequop Mountains","kind":"range","lat":40.95,"lon":-114.6,"line":[[-114.62,41.25],[-114.6,41.08],[-114.58,40.9],[-114.6,40.7],[-114.62,40.55]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Folded limestone ridges east of Wells","blurb":"The Pequops are a classic Great Basin range of Paleozoic limestone, tilted and folded. Newer gold discoveries in their foothills extended Nevada's gold belts eastward.","lookFor":"A north-south ridge of gray-banded rock layers that I-80 crosses at Pequop Summit.","fact":"Pequop Summit on I-80 is about 6,967 ft","priority":3},
 {"id":"wendover","name":"Wendover & West Wendover","kind":"city","lat":40.737,"lon":-114.037,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Casino town straddling the state line","blurb":"Wendover sits on the western edge of the Bonneville Salt Flats at the Nevada-Utah line. Casinos crowd the Nevada side.","lookFor":"A small town where the white salt flats meet the mountains, with the old airfield's runways just south.","history":"The Enola Gay's crew and the 509th Composite Group trained at Wendover Army Air Field in 1944-45.","fact":"509th Composite Group trained here, 1944-45","priority":2},
 {"id":"pilot-peak","name":"Pilot Peak","kind":"peak","lat":41.0215,"lon":-114.0778,"elevFt":10716,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Beacon for emigrants crossing the salt","blurb":"Pilot Peak rises more than a mile above the salt desert, the tallest of the Pilot Range. Springs at its foot were the first fresh water after the crossing of the Great Salt Lake Desert.","lookFor":"A tall pyramid of a peak north of Wendover, standing high above the white flats.","history":"Frémont used it as a guide in 1845. The Donner Party, crossing the salt on the Hastings Cutoff in 1846, aimed for its springs.","fact":"10,716 ft","priority":2},
 {"id":"silver-island-mountains","name":"Silver Island Mountains","kind":"range","lat":40.88,"lon":-113.93,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Rocky islands in a sea of salt","blurb":"These jagged limestone ridges were islands in ancient Lake Bonneville. Wave-cut terraces still ring their sides like bathtub rings.","lookFor":"Dark, craggy hills rising directly from the white salt northeast of Wendover, with horizontal shoreline benches.","history":"The Donner-Reed party crossed through a gap here, now called Donner-Reed Pass, in 1846.","fact":"Islands in Lake Bonneville ~15,000 years ago","priority":2},
 {"id":"bonneville-salt-flats","name":"Bonneville Salt Flats","kind":"saltflat","lat":40.77,"lon":-113.85,"extentKm":30,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Brilliant white crust, famous for speed","blurb":"The Bonneville Salt Flats are a crust of salt left as ancient Lake Bonneville evaporated. Winter rains dissolve the surface and wind smooths it back to a level, hard plate each summer. The crust has thinned over the past century.","lookFor":"Dazzling white flat ground east of Wendover on both sides of I-80, with a straight line of road and race tracks scratched across it.","history":"Racers have chased land speed records here since the early 1900s. Gary Gabelich reached about 622 mph in the Blue Flame in 1970.","nearby":["Speedway area north of I-80","Silver Island Mountains to the north"],"fact":"622 mph, Blue Flame, 1970","era":"Lake Bonneville evaporite","priority":1},
 {"id":"great-salt-lake-desert","name":"Great Salt Lake Desert","kind":"basin","lat":40.9,"lon":-113.4,"extentKm":150,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Former lake floor, now mud and salt","blurb":"This vast flat is the dried western floor of Lake Bonneville. Salt, mud and shallow ponds cover it. Mirages often turn the horizon into shimmering water.","lookFor":"Endless pale tan and white flats with faint drainage patterns and the dark, straight line of the railroad and I-80 cutting across.","history":"Emigrants on the Hastings Cutoff of 1846 struggled across 80 miles of this ground without water.","fact":"Hastings Cutoff: ~80 miles without water","priority":2},
 {"id":"great-salt-lake","name":"Great Salt Lake","kind":"lake","lat":41.1,"lon":-112.5,"elevFt":4195,"extentKm":120,"line":[[-112.95,41.22],[-112.85,41.22],[-112.67,41.22],[-112.52,41.23]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Pink north, blue south, split by a railroad","blurb":"Great Salt Lake is the largest remnant of Lake Bonneville. In 1959 a solid rock railroad causeway cut the lake in two. Rivers feed only the south arm, so the north arm became far saltier and is colored pink to red by salt-loving microbes.","lookFor":"Look for a straight east-west line across the lake: the causeway. North of it the water is rose or rusty red; south of it, blue-green. Pale salt and mudflats rim the shrinking shoreline.","history":"The Southern Pacific's Lucin Cutoff crossed the lake on a wooden trestle in 1904; the rock-fill causeway replaced it in 1959.","nearby":["Railroad causeway splitting the lake","Antelope Island","Spiral Jetty on the north shore","Mineral evaporation ponds along the shore"],"fact":"North arm can exceed 25% salt","era":"Lake Bonneville remnant","priority":1},
 {"id":"antelope-island","name":"Antelope Island","kind":"landmark","lat":40.96,"lon":-112.21,"elevFt":6596,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Ancient rock island with a bison herd","blurb":"Antelope Island is the largest island in Great Salt Lake. Its core includes some of the oldest rock in Utah, metamorphic gneiss about 1.7 billion years old. Lake Bonneville shorelines ring its slopes.","lookFor":"A long brown mountainous island in the southeast part of the lake, joined to the mainland by a thin causeway road.","history":"Twelve bison were ferried to the island in 1893; their descendants still roam it.","fact":"Bison herd started with 12 animals in 1893","era":"Precambrian gneiss","priority":2},
 {"id":"spiral-jetty","name":"Spiral Jetty","kind":"landmark","lat":41.4375,"lon":-112.6686,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Land art coiling into red water","blurb":"Robert Smithson built Spiral Jetty from black basalt and mud on the north shore of Great Salt Lake. It was submerged for decades, then re-emerged as the lake dropped. Now it often sits on dry ground crusted with white salt.","lookFor":"At the tip of the Rozel Point area on the northeast shore of the north arm, a tiny dark coil against pink water or white salt.","history":"Smithson completed it in April 1970. It now belongs to the Dia Art Foundation.","fact":"1,500 ft long","priority":2},
 {"id":"promontory-summit","name":"Promontory Summit (Golden Spike)","kind":"history","lat":41.6178,"lon":-112.5514,"elevFt":4902,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Where the rails met in 1869","blurb":"The Central Pacific and Union Pacific met at Promontory Summit to complete the first transcontinental railroad. The grades both companies built are still visible side by side, cut into the hills.","lookFor":"A low pass north of the Promontory Mountains peninsula, north of Great Salt Lake. Look for thin parallel lines of old railroad grade.","history":"Leland Stanford swung at the last spike on May 10, 1869, and the news went out by telegraph.","fact":"Golden spike driven May 10, 1869","priority":1},
 {"id":"bear-river-refuge","name":"Bear River Migratory Bird Refuge","kind":"lake","lat":41.46,"lon":-112.27,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Wetland where a long river ends","blurb":"The Bear River ends in a broad delta of marsh and ponds at the northeast corner of Great Salt Lake. Fresh river water meeting salt lake water creates some of the richest bird habitat in the West.","lookFor":"Geometric diked ponds and green-brown marsh at the mouth of the Bear River, west of Brigham City.","history":"The refuge was established in 1928.","fact":"The Bear River runs about 350 miles and never reaches the sea","priority":2},
 {"id":"bear-lake","name":"Bear Lake","kind":"lake","lat":41.96,"lon":-111.33,"elevFt":5924,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The Caribbean of the Rockies","blurb":"Bear Lake fills a fault-bounded valley on the Utah-Idaho line. Tiny particles of calcium carbonate suspended in its water give it a vivid turquoise color.","lookFor":"A long turquoise lake, about 20 miles long, set in a high valley with the state line running across its middle.","fact":"About 20 miles long","era":"Fault basin, >250,000 yrs old","priority":2},
 {"id":"wasatch-range","name":"Wasatch Range","kind":"range","lat":40.9,"lon":-111.75,"elevFt":11928,"line":[[-111.73,41.95],[-111.85,41.6],[-111.96,41.36],[-111.86,41.18],[-111.8,40.9],[-111.75,40.65],[-111.65,40.39],[-111.6,40.15],[-111.76,39.82]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Steep fault wall above Salt Lake City","blurb":"The Wasatch Range rises abruptly along the Wasatch Fault, one of the most active faults in the interior West. The mountains go up as the valleys drop, a few feet per large earthquake. Old Lake Bonneville shorelines are etched along its base.","lookFor":"A steep wall of mountains on the east side of the Salt Lake and Ogden valleys, snowy above 9,000 ft, with sharp canyon mouths and level benches along its foot.","history":"Mormon pioneers emerged from its canyons into the Salt Lake Valley in July 1847.","nearby":["Ben Lomond above Ogden","Mount Timpanogos","Little and Big Cottonwood canyons"],"fact":"Wasatch Fault runs about 240 miles","era":"Uplift since ~10 Ma","priority":1},
 {"id":"mount-timpanogos","name":"Mount Timpanogos","kind":"peak","lat":40.3908,"lon":-111.6458,"elevFt":11752,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The Wasatch's signature summit","blurb":"Timpanogos is a massive block of limestone and quartzite rising above Utah Valley. Its long ridge, cirques and permanent snowfield make it one of the best-known Wasatch peaks.","lookFor":"A huge gray massif with a long summit ridge southeast of the Salt Lake Valley.","fact":"11,752 ft","priority":3},
 {"id":"salt-lake-city","name":"Salt Lake City","kind":"city","lat":40.76,"lon":-111.89,"elevFt":4226,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A city on an ancient lake bottom","blurb":"Salt Lake City sits on the flat floor of former Lake Bonneville, between the Wasatch and Oquirrh mountains. Its wide street grid was laid out from Temple Square.","lookFor":"A dense grid filling the valley floor, with the Wasatch wall to the east and the Oquirrhs to the southwest.","history":"Brigham Young's pioneers arrived in July 1847 and laid out the city within days.","fact":"Founded July 1847","priority":2},
 {"id":"lake-bonneville-shorelines","name":"Lake Bonneville shorelines","kind":"geology","lat":40.78,"lon":-111.82,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Bathtub rings of an ice-age lake","blurb":"Lake Bonneville rose to about 5,100 ft above sea level, then burst through Red Rock Pass in Idaho about 18,000 years ago and dropped some 350 ft in a catastrophic flood. Waves cut level terraces at each long pause. They show up as perfectly horizontal benches along mountain fronts.","lookFor":"Level lines and terraces etched across the foot of the Wasatch, Oquirrh and desert ranges, all at the same height, like rings in a drained bathtub.","nearby":["Bonneville shoreline benches above Salt Lake City","Provo shoreline lower down"],"fact":"Covered about 20,000 square miles","era":"Pleistocene, ~30,000-13,000 yrs ago","priority":1},
 {"id":"bingham-canyon-mine","name":"Bingham Canyon Mine","kind":"mine","lat":40.523,"lon":-112.151,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A copper pit you can see from orbit","blurb":"Bingham Canyon is a giant open pit in the Oquirrh Mountains, mining a porphyry copper deposit formed above a cooling magma body. Its terraced walls spiral down more than half a mile.","lookFor":"A huge stepped bowl in the Oquirrh Mountains southwest of Salt Lake City, with orange-brown waste dumps spilling down the slopes.","history":"Open-pit mining began here in 1906. A massive slide in April 2013 was among the largest non-volcanic landslides in recorded North American history.","fact":"About 2.5 miles wide and over half a mile deep","era":"Eocene porphyry copper, ~38 Ma","priority":1},
 {"id":"uinta-mountains","name":"Uinta Mountains & Kings Peak","kind":"range","lat":40.78,"lon":-110.4,"elevFt":13528,"line":[[-111.1,40.65],[-110.85,40.7],[-110.6,40.75],[-110.37,40.776],[-110.1,40.8],[-109.8,40.85],[-109.5,40.85]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"The rare range that runs east-west","blurb":"The Uintas are an arch of ancient red quartzite and sandstone pushed up during the Laramide mountain-building. Glaciers carved basins and hundreds of lakes along their crest. Kings Peak is the highest point in Utah.","lookFor":"A long east-west line of high, broad-backed summits south of the track, with reddish rock, glacial basins and lingering snow.","nearby":["Kings Peak, highest in Utah","Flaming Gorge at the east end"],"fact":"Kings Peak 13,528 ft","era":"Neoproterozoic quartzite, ~750 Ma; uplift ~70-40 Ma","priority":1},
 {"id":"flaming-gorge","name":"Flaming Gorge Reservoir","kind":"reservoir","lat":41.15,"lon":-109.55,"line":[[-109.42,40.91],[-109.55,40.98],[-109.62,41.05],[-109.57,41.2],[-109.52,41.35],[-109.47,41.5]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Red cliffs drowned by the Green River","blurb":"Flaming Gorge Dam backs up the Green River for 91 miles, from Utah far into Wyoming. At its south end the river had cut into the bright red rock of the Uinta uplift.","lookFor":"A long, narrow reservoir running north-south, with red cliffs at its southern Utah end and pale badlands along its Wyoming shores.","history":"John Wesley Powell named Flaming Gorge in 1869 for its glowing red walls. The dam was completed in 1964.","fact":"91 miles long","priority":1},
 {"id":"fossil-butte","name":"Fossil Butte","kind":"geology","lat":41.856,"lon":-110.769,"elevFt":7500,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A 52-million-year-old lake in stone","blurb":"Fossil Butte preserves the bed of Fossil Lake, a subtropical lake where fish, palms, birds, bats and crocodiles were buried in fine limestone layers. Fossils here are so complete that scales and skin can be seen.","lookFor":"A flat-topped butte with pale buff and white layered cliffs west of Kemmerer.","fact":"About 52 million years old","era":"Eocene Green River Formation","priority":2},
 {"id":"green-river-formation","name":"Green River Formation","kind":"geology","lat":41.53,"lon":-109.47,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Layer-cake cliffs of ancient lakes","blurb":"Some 50 million years ago, large lakes covered parts of Wyoming, Utah and Colorado. Their fine layers, one pair per year in places, built the striped cliffs around Green River. The same lakes left the world's largest known deposit of trona, mined nearby for soda ash.","lookFor":"Pale buff, gray and white banded cliffs and buttes around the town of Green River, with tall pinnacles like Castle Rock.","nearby":["Castle Rock at Green River","Trona mines west of town"],"fact":"World's largest known trona deposit","era":"Eocene lake deposits, ~53-45 Ma","priority":2},
 {"id":"boars-tusk","name":"Boar's Tusk","kind":"volcano","lat":41.9628,"lon":-109.1972,"elevFt":7101,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Lone volcanic throat in the Red Desert","blurb":"Boar's Tusk is the hardened plug of an old volcano, made of a rare potassium-rich rock called lamproite. The softer volcano around it has eroded away, leaving the plug standing alone.","lookFor":"A single dark spike north of Rock Springs at the west end of the Killpecker Dunes.","fact":"Rises about 400 ft above the plain","era":"Leucite Hills lamproite, ~2.5 Ma","priority":2},
 {"id":"killpecker-dunes","name":"Killpecker Sand Dunes","kind":"dunes","lat":42.02,"lon":-108.85,"line":[[-109.35,41.93],[-109.1,41.97],[-108.85,42.02],[-108.6,42.07],[-108.35,42.12]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Active dunes marching across the Red Desert","blurb":"Wind funnels sand eastward from the Green River Basin into a long belt of active dunes. Some are bare and moving, others held in place by sagebrush. Snow buried in the dunes can survive into summer.","lookFor":"A long belt of pale tan sand with crescent ridges, running east-northeast from Boar's Tusk.","fact":"Dune field runs about 55 miles","priority":2},
 {"id":"great-divide-basin","name":"Great Divide Basin & Red Desert","kind":"basin","lat":41.95,"lon":-108.2,"extentKm":100,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Where the Continental Divide splits open","blurb":"Here the Continental Divide splits in two and wraps around a basin with no outlet. Rain and snowmelt that fall inside drain to neither ocean and evaporate in playas. The Red Desert around it holds wild horses, pronghorn and big dune fields.","lookFor":"A wide, nearly empty basin of sage, badlands and white alkali flats, with few roads and no rivers leaving it.","history":"The Overland Trail and the Union Pacific skirted its southern edge.","fact":"Nearly 4,000 sq mi with no outlet","priority":1},
 {"id":"wind-river-range","name":"Wind River Range","kind":"range","lat":42.95,"lon":-109.4,"elevFt":13804,"line":[[-108.85,42.45],[-109.05,42.65],[-109.25,42.83],[-109.48,43],[-109.65,43.18],[-109.85,43.35],[-110,43.5]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Granite spine of Wyoming","blurb":"The Wind Rivers are a core of ancient granite and gneiss, much of it more than 2.5 billion years old, pushed up during the Laramide mountain-building. They hold Wyoming's highest peaks and the largest glaciers in the American Rockies.","lookFor":"A long, high wall of gray granite peaks and glaciers to the north, running northwest from South Pass.","nearby":["Gannett Peak, highest in Wyoming","Cirque of the Towers","South Pass at the south end"],"fact":"Gannett Peak, 13,804 ft","era":"Archean granite, >2.5 Ga","priority":1},
 {"id":"grand-teton","name":"Grand Teton","kind":"peak","lat":43.741,"lon":-110.802,"elevFt":13775,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Jagged skyline far to the north","blurb":"The Tetons rise along an active fault, which explains their abrupt front with no foothills. The range is among the youngest in the Rockies.","lookFor":"Only on very clear days: a sharp, jagged cluster of peaks on the far northern horizon.","fact":"13,775 ft","era":"Fault-block uplift, <10 Ma","priority":3},
 {"id":"south-pass","name":"South Pass","kind":"history","lat":42.36,"lon":-108.92,"elevFt":7412,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The gentle gateway west","blurb":"South Pass is a broad saddle between the Wind River Range and the Great Divide Basin, so gentle that wagons could cross the Continental Divide without a steep climb.","lookFor":"A wide, open sagebrush plain at the south tip of the Wind River Range, with the Oregon Buttes nearby.","history":"Robert Stuart's party crossed it in 1812. From the 1840s, Oregon, California and Mormon trail emigrants by the hundreds of thousands funneled through.","fact":"7,412 ft","priority":2},
 {"id":"independence-rock","name":"Independence Rock","kind":"history","lat":42.494,"lon":-107.132,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Register of the desert","blurb":"Independence Rock is a granite dome on the Sweetwater River. Emigrants carved and painted their names on it by the thousands.","lookFor":"A rounded, whale-backed granite dome beside a small river in open country.","history":"Emigrants aimed to reach it by July 4 to stay ahead of Sierra snows.","nearby":["Devil's Gate canyon, about 5 miles southwest","Sweetwater River"],"fact":"Rises about 130 ft","priority":2},
 {"id":"medicine-bow-snowy-range","name":"Medicine Bow Mountains & Snowy Range","kind":"range","lat":41.36,"lon":-106.32,"elevFt":12014,"line":[[-106.1,40.65],[-106.15,40.95],[-106.25,41.2],[-106.3175,41.36],[-106.35,41.5]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"White quartzite that looks like snow","blurb":"The Snowy Range is capped by white quartzite, ancient beach sands baked into hard rock about 2 billion years ago. The pale cliffs can look snow-covered even in late summer. Glaciers carved lakes at the foot of Medicine Bow Peak.","lookFor":"A high ridge with gleaming white cliffs and small lakes right below the track, west of Laramie.","nearby":["Medicine Bow Peak","Lake Marie below the cliffs","Snowy Range Pass road"],"fact":"Medicine Bow Peak, 12,014 ft","era":"Paleoproterozoic quartzite","priority":1},
 {"id":"elk-mountain","name":"Elk Mountain","kind":"peak","lat":41.638,"lon":-106.498,"elevFt":11156,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Lone sentinel of the Overland Trail","blurb":"Elk Mountain is an isolated mountain at the north tip of the Medicine Bow Mountains, standing far above the plains around it.","lookFor":"A big, lone, dark-forested mountain north of the Snowy Range, often with snow on top.","history":"The Overland Trail and stage line ran along its base in the 1860s.","fact":"11,156 ft","priority":2},
 {"id":"laramie-range-vedauwoo","name":"Laramie Range & Vedauwoo","kind":"range","lat":41.16,"lon":-105.38,"elevFt":10272,"line":[[-105.3,40.85],[-105.38,41.16],[-105.45,41.5],[-105.5,41.85],[-105.44,42.27],[-105.5,42.55]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Pink granite towers and the Gangplank","blurb":"The Laramie Range is a Laramide uplift of pink Sherman Granite about 1.4 billion years old. At Vedauwoo the granite weathers along cracks into stacked boulders and rounded towers.","lookFor":"Pink-gray granite hills and knobs between Cheyenne and Laramie, with jumbled rock outcrops scattered through pine forest.","nearby":["Vedauwoo rock towers","Ames Monument at Sherman Summit","Laramie Peak far to the north"],"fact":"Sherman Granite about 1.4 billion years old","era":"Mesoproterozoic granite","priority":2},
 {"id":"laramie-peak","name":"Laramie Peak","kind":"peak","lat":42.2689,"lon":-105.4422,"elevFt":10272,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Oregon Trail landmark on the western skyline","blurb":"Laramie Peak is the highest summit of the Laramie Range, a dark granite peak visible for great distances across the plains.","lookFor":"A dark, isolated summit standing above the northern Laramie Range.","history":"Emigrants on the Oregon Trail saw it for days as the first real mountain on their route.","fact":"10,272 ft","priority":2},
 {"id":"gangplank","name":"The Gangplank","kind":"geology","lat":41.15,"lon":-105.12,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The ramp that let the railroad climb the Rockies","blurb":"Along most of the Front Range the plains end at steep mountain walls. At the Gangplank, a continuous slope of Ogallala sediment still rests against the granite, creating a smooth ramp from the plains to the summit.","lookFor":"A long, gentle grassy slope rising west from Cheyenne straight up onto the granite of the Laramie Range.","history":"Union Pacific surveyors used it in 1867-68 to reach Sherman Summit.","fact":"Sherman Summit, 8,247 ft, high point of the first transcontinental railroad","priority":2},
 {"id":"longs-peak","name":"Longs Peak & Rocky Mountain NP","kind":"peak","lat":40.2548,"lon":-105.6151,"elevFt":14259,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Colorado's northernmost fourteener","blurb":"Longs Peak is a flat-topped granite peak with a sheer east face called the Diamond. It towers over Rocky Mountain National Park and the Front Range.","lookFor":"A broad-shouldered, flat-topped summit far to the south, highest along the Front Range skyline.","history":"John Wesley Powell's party made the first recorded ascent in 1868.","fact":"14,259 ft","priority":2},
 {"id":"scotts-bluff","name":"Scotts Bluff","kind":"landmark","lat":41.834,"lon":-103.707,"elevFt":4659,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The trail's great bluff on the North Platte","blurb":"Scotts Bluff is a remnant of the High Plains, capped by harder sandstone that protects softer layers of silt and volcanic ash below. It towers above the North Platte River.","lookFor":"A massive, steep-sided bluff on the south side of the North Platte, with the towns of Gering and Scottsbluff at its base.","history":"Oregon Trail wagons passed through Mitchell Pass beside the bluff; ruts are still visible.","nearby":["Mitchell Pass","North Platte River","Wildcat Hills to the south"],"fact":"Rises about 800 ft above the river","priority":1},
 {"id":"chimney-rock","name":"Chimney Rock","kind":"landmark","lat":41.7042,"lon":-103.3481,"elevFt":4226,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The trail's most famous spire","blurb":"Chimney Rock is a thin spire of Brule clay and volcanic ash, capped by sandstone, on a cone-shaped base. It is slowly crumbling.","lookFor":"A thin needle on a cone south of the North Platte, between Bridgeport and Scotts Bluff.","history":"Chimney Rock is mentioned in emigrant journals more than any other landmark on the trail.","nearby":["Courthouse and Jail Rocks to the east"],"fact":"Spire stands about 300 ft above the valley","priority":1},
 {"id":"lake-mcconaughy","name":"Lake McConaughy","kind":"reservoir","lat":41.25,"lon":-101.8,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Nebraska's inland sea with white sand beaches","blurb":"Kingsley Dam blocks the North Platte here, at the southern edge of the Sandhills. Wind-blown sand forms broad white beaches around the lake.","lookFor":"A long blue lake with bright white beaches, set in tan rolling sandhills, north of Ogallala.","history":"Kingsley Dam was completed in 1941, then one of the largest hydraulic-fill dams in the world.","nearby":["Kingsley Dam at the east end","Lake Ogallala below the dam","Ash Hollow to the west"],"fact":"About 22 miles long","priority":2},
 {"id":"nebraska-sandhills","name":"Nebraska Sandhills","kind":"dunes","lat":42,"lon":-101,"extentKm":300,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A sea of grass-covered dunes","blurb":"The Sandhills are the largest dune field in the Western Hemisphere, stabilized by native grasses. Groundwater from the Ogallala Aquifer surfaces between the dunes as hundreds of lakes and wet meadows.","lookFor":"Smooth, rolling hills of tan or green with scattered blue lakes in the hollows and very few roads or fields.","nearby":["Hundreds of small lakes","Dismal and Middle Loup rivers"],"fact":"About 20,000 square miles","era":"Holocene dunes on Ogallala aquifer","priority":1},
 {"id":"platte-river","name":"Platte River crane flyway","kind":"river","lat":40.7,"lon":-98.9,"line":[[-100.69,41.11],[-100,40.95],[-99.5,40.75],[-99.08,40.69],[-98.6,40.75],[-98.2,40.92],[-97.6,41.25],[-97.35,41.4],[-96.5,41.45],[-96.2,41.2],[-95.88,41.03]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"A mile wide, an inch deep, and full of cranes","blurb":"The Platte is a broad, braided river of sandbars and shallow channels. Every March, roughly half a million or more sandhill cranes gather on the Big Bend reach, roosting in the shallow water at night and feeding in cornfields by day.","lookFor":"A wide, braided band of sandbars and trees running east-west, flanked by I-80 and the Union Pacific main line.","history":"The Great Platte River Road carried Oregon, California and Mormon trail traffic along its banks.","nearby":["Big Bend crane roosts near Kearney","Confluence of North and South Platte at North Platte"],"fact":"More than 500,000 cranes each spring","priority":1},
 {"id":"center-pivots","name":"Center-pivot irrigation circles","kind":"plains","lat":41.5,"lon":-98,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Green coins on the plains","blurb":"A center pivot is a long sprinkler arm that rotates around a well, creating a perfect circle of crops. Nebraska has more irrigated acres than any other state, much of it watered from the Ogallala Aquifer.","lookFor":"Perfect green or brown circles packed into square-mile grids, with dry corners between them.","history":"Nebraska farmer Frank Zybach invented the center pivot in the late 1940s and patented it in 1952.","fact":"A quarter-mile arm waters about 130 acres","priority":1},
 {"id":"bailey-yard","name":"Bailey Yard","kind":"landmark","lat":41.13,"lon":-100.83,"legs":["ORD-SMF","SMF-ORD"],"tagline":"The world's largest rail yard","blurb":"Union Pacific's Bailey Yard in North Platte sorts thousands of rail cars a day using hump yards where gravity rolls cars onto their tracks.","lookFor":"A long fan of parallel tracks on the west side of North Platte.","fact":"About 2,850 acres","priority":3},
 {"id":"agate-fossil-beds","name":"Agate Fossil Beds","kind":"geology","lat":42.42,"lon":-103.73,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Mammal graveyard of the Miocene","blurb":"Bone beds here hold rhinos, beardogs and land beavers that died around a waterhole during drought. Corkscrew-shaped fossils called devil's corkscrews are the burrows of an extinct beaver.","lookFor":"Two small buttes beside the winding Niobrara River in open grassland.","fact":"About 20 million years old","era":"Miocene","priority":2},
 {"id":"ashfall-fossil-beds","name":"Ashfall Fossil Beds","kind":"geology","lat":42.425,"lon":-98.158,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Nebraska's Pompeii","blurb":"About 12 million years ago a supereruption in southwestern Idaho dropped volcanic ash across Nebraska. Rhinos, horses and camels gathered at a waterhole here died from breathing the ash and were buried whole.","lookFor":"Not visible itself; look for rolling cropland and pastures in northeast Nebraska.","fact":"Ash traveled about 1,000 miles from Idaho","era":"Miocene, ~12 Ma","priority":2},
 {"id":"niobrara-river","name":"Niobrara River","kind":"river","lat":42.85,"lon":-100.3,"line":[[-103.7,42.42],[-102.5,42.65],[-101.5,42.85],[-100.55,42.88],[-99.8,42.78],[-99,42.75],[-98,42.77]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"A canyon river at the edge of the Sandhills","blurb":"The Niobrara cuts a narrow, steep canyon with spring-fed waterfalls. Northern, eastern and western forests meet in its valley.","lookFor":"A winding, tree-lined canyon north of the Sandhills, darker green than the surrounding grassland.","nearby":["Smith Falls near Valentine"],"fact":"Smith Falls drops 63 ft","priority":3},
 {"id":"loess-hills","name":"Loess Hills","kind":"geology","lat":41.9,"lon":-96,"line":[[-96.4,42.55],[-96.2,42.2],[-96.05,41.9],[-95.9,41.55],[-95.82,41.2],[-95.75,40.9],[-95.55,40.6]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Hills built of windblown glacial dust","blurb":"During the ice ages, winds picked up fine silt from Missouri River floodplains and piled it on the east bank. The deposits are thick enough to form steep ridges with knife-edge crests.","lookFor":"A narrow band of steep, wrinkled hills along the east side of the Missouri River valley, often prairie on top and trees in the folds.","fact":"Loess here can exceed 60 ft thick","era":"Pleistocene loess","priority":1},
 {"id":"missouri-omaha","name":"Missouri River at Omaha","kind":"river","lat":41.26,"lon":-95.92,"line":[[-96.3,42],[-96.1,41.7],[-95.95,41.45],[-95.92,41.26],[-95.86,41.05]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Big Muddy at the old gateway west","blurb":"The Missouri is the longest river in North America. Engineers straightened and narrowed it into a channel, leaving oxbow lakes and old meanders behind.","lookFor":"A wide brown river with crescent oxbow lakes on its floodplain, between Omaha and Council Bluffs.","history":"Lewis and Clark held council with Otoe and Missouria leaders near here in 1804. The Union Pacific started building west from Omaha in 1865.","nearby":["Carter Lake oxbow","Omaha skyline","Council Bluffs"],"fact":"About 2,340 miles long","priority":2},
 {"id":"des-moines","name":"Des Moines","kind":"city","lat":41.586,"lon":-93.625,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Capital on the last glacier's doorstep","blurb":"Des Moines sits at the southern tip of the Des Moines Lobe, the last glacier to push into Iowa. North of the city the land is younger and dotted with glacial potholes.","lookFor":"A mid-size city with a gold-domed Capitol, at the junction of the Des Moines and Raccoon rivers.","fact":"Ice reached here about 14,000 years ago","priority":2},
 {"id":"quad-cities","name":"Mississippi River & Quad Cities","kind":"river","lat":41.52,"lon":-90.55,"line":[[-90.65,42.5],[-90.42,42.28],[-90.2,42],[-90.18,41.82],[-90.35,41.55],[-90.55,41.52],[-90.8,41.45],[-91.05,41.42]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Where the Mississippi flows west","blurb":"At the Quad Cities the Mississippi turns and flows west for miles. Locks and dams turn the river into a series of pools.","lookFor":"A broad river with islands, backwaters and lock-and-dam structures, lined by cities on both banks.","history":"The first railroad bridge across the Mississippi opened here in 1856. Abraham Lincoln defended it in court after a steamboat crashed into it.","nearby":["Rock Island Arsenal on an island","Lock and Dam 15"],"fact":"First railroad bridge across the Mississippi, 1856","priority":2},
 {"id":"driftless-area","name":"Driftless Area","kind":"geology","lat":42.6,"lon":-90.9,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Land the glaciers missed","blurb":"Ice sheets flowed around this region during the last ice age, leaving no glacial drift. Streams carved deep valleys, bluffs and caves into the limestone.","lookFor":"Steep wooded ridges and deep valleys around the Mississippi near Dubuque, unlike the smooth farmland on either side.","fact":"Spans parts of 4 states","priority":2},
 {"id":"chicago","name":"Chicago","kind":"city","lat":41.88,"lon":-87.63,"legs":["ORD-SMF","SMF-ORD"],"tagline":"City of big shoulders on a reversed river","blurb":"Chicago is built on the flat bed of glacial Lake Chicago. Engineers reversed the Chicago River in 1900 so sewage would flow away from Lake Michigan.","lookFor":"A skyline of towers along the lakefront, with a grid of streets spreading inland and O'Hare's runways to the northwest.","history":"Chicago grew into the nation's rail hub after 1850.","fact":"Willis Tower 1,451 ft","priority":2},
 {"id":"lake-michigan","name":"Lake Michigan","kind":"lake","lat":42.1,"lon":-87.45,"legs":["ORD-SMF","SMF-ORD"],"tagline":"A freshwater sea on Chicago's doorstep","blurb":"Lake Michigan fills a basin scoured by ice sheets. It is the only Great Lake entirely within the United States.","lookFor":"Deep blue water to the east of Chicago that stretches to the horizon.","fact":"About 923 ft deep","priority":2},
 {"id":"wheeler-peak","name":"Great Basin NP & Wheeler Peak","kind":"peak","lat":38.986,"lon":-114.314,"elevFt":13063,"legs":["ORD-SMF","SMF-ORD"],"tagline":"Glacier and bristlecones in the desert","blurb":"Wheeler Peak in the Snake Range shelters Nevada's only glacier and groves of bristlecone pines, some of the oldest living things on Earth.","lookFor":"Far to the south on a clear day: a high, snowy peak rising above the desert.","history":"In 1964 a researcher cut down a bristlecone later found to be about 4,900 years old.","fact":"13,063 ft","priority":2},
 {"id":"california-trail","name":"California Trail","kind":"history","lat":40.6,"lon":-117,"line":[[-114.96,41.11],[-115.76,40.83],[-116.93,40.64],[-117.73,40.97],[-118.47,40.18],[-118.62,39.97],[-119,39.6],[-119.8,39.53],[-120.33,39.32],[-121,39],[-121.49,38.58]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"Following the Humboldt to the gold fields","blurb":"The trail followed the Humboldt River across Nevada, crossed the Forty Mile Desert, then climbed the Sierra. Its route matches I-80 for long stretches.","lookFor":"Trace the Humboldt River corridor and I-80; the trail ran along the same line.","history":"More than 250,000 emigrants used it during the Gold Rush years.","fact":"More than 250,000 emigrants","priority":2},
 {"id":"oregon-trail","name":"Oregon Trail","kind":"history","lat":42,"lon":-104.5,"line":[[-98.9,40.65],[-100.7,41.1],[-102.12,41.29],[-103.35,41.7],[-103.7,41.83],[-104.56,42.2],[-106.3,42.85],[-107.13,42.49],[-108.92,42.36],[-110.39,41.32]],"legs":["ORD-SMF","SMF-ORD"],"tagline":"The great road up the Platte","blurb":"From the Missouri River the trail followed the Platte and North Platte rivers to the Sweetwater and South Pass.","lookFor":"The North Platte valley with Chimney Rock and Scotts Bluff along it.","history":"Roughly 400,000 people traveled the Oregon, California and Mormon trails between the 1840s and 1860s.","fact":"About 2,000 miles long","priority":2},
 {"id":"cross-il-ia-wb","name":"Illinois / Iowa line (Mississippi River)","kind":"crossing","lat":41.9571,"lon":-90.17,"legs":["ORD-SMF"],"tagline":"Crossing the Mississippi","blurb":"The Mississippi River forms the Illinois-Iowa line. Its valley here is lined with limestone bluffs and backwater sloughs.","lookFor":"A broad river directly below, with wooded islands, backwaters and a lock and dam.","fact":"Drains about 40% of the lower 48 states","priority":2},
 {"id":"cross-ia-ne-wb","name":"Iowa / Nebraska line (Missouri River)","kind":"crossing","lat":41.6247,"lon":-95.92,"legs":["ORD-SMF"],"tagline":"Crossing the Missouri","blurb":"The Missouri River forms the Iowa-Nebraska line. Its floodplain is dotted with oxbow lakes left as engineers straightened the channel.","lookFor":"A wide brown river with curving oxbow lakes and the steep Loess Hills on the Iowa side.","fact":"Longest river in North America","priority":2},
 {"id":"cross-100th-wb","name":"100th meridian","kind":"crossing","lat":41.5257,"lon":-100,"legs":["ORD-SMF"],"tagline":"Where the arid West begins","blurb":"The 100th meridian roughly separates the humid East from the dry West. West of it, average rainfall drops below about 20 inches a year, too little for most crops without irrigation.","lookFor":"Notice more center-pivot circles, fewer trees and more open grassland to the west.","history":"John Wesley Powell argued in 1878 that land west of this line needed different laws for water and settlement.","fact":"About 20 inches of rain a year","priority":2},
 {"id":"cross-tz-central-mountain-wb","name":"Central to Mountain Time","kind":"crossing","lat":41.5209,"lon":-101.25,"legs":["ORD-SMF"],"tagline":"Set your watch back an hour","blurb":"In western Nebraska the time-zone line falls between Lincoln and Keith counties, near the Sutherland and Paxton exits on I-80. Ogallala and the panhandle keep Mountain Time.","lookFor":"The North Platte and South Platte valleys converge to the east; Lake McConaughy lies just ahead to the west.","fact":"Clocks go back 1 hour westbound","priority":2},
 {"id":"cross-ne-wy-wb","name":"Nebraska / Wyoming line","kind":"crossing","lat":41.4227,"lon":-104.053,"legs":["ORD-SMF"],"tagline":"Into Wyoming","blurb":"The Nebraska-Wyoming line follows a meridian surveyed across open high plains. Ground elevation here is about a mile above sea level.","lookFor":"Shortgrass prairie and wheat strips; the line itself is invisible except where roads jog.","fact":"Line runs along about 104.05 W","priority":3},
 {"id":"cross-continental-divide-wb","name":"Continental Divide","kind":"crossing","lat":41.2596,"lon":-107.1,"legs":["ORD-SMF"],"tagline":"Atlantic on one side, Pacific on the other","blurb":"The Continental Divide runs along the north end of the Sierra Madre here. Rain falling east of it flows to the North Platte and the Gulf of Mexico; rain to the west flows to the Little Snake, Colorado River and Gulf of California. Just north, the divide splits around the Great Divide Basin.","lookFor":"Forested Sierra Madre ridges to the south fading into open sagebrush basin to the west.","fact":"Divide splits around a 4,000 sq mi basin just north","priority":1},
 {"id":"cross-wy-ut-wb","name":"Wyoming / Utah line","kind":"crossing","lat":41,"lon":-110.43,"legs":["ORD-SMF"],"tagline":"Into Utah","blurb":"This part of the Wyoming-Utah line follows a parallel and a meridian drawn by surveyors, not any natural feature.","lookFor":"Sagebrush basin country with the Uinta Mountains rising to the south.","fact":"Wyoming's borders are all straight lines","priority":3},
 {"id":"cross-great-basin-rim-east-wb","name":"Great Basin rim (east)","kind":"crossing","lat":40.969,"lon":-110.75,"legs":["ORD-SMF"],"tagline":"Rivers stop reaching the sea","blurb":"On the north slope of the Uintas, the Bear River drains toward Great Salt Lake while neighboring streams flow to the Green and Colorado rivers. West of this divide, no water reaches the ocean.","lookFor":"Forested north flank of the Uinta Mountains to the south, with streams fanning out across sagebrush.","fact":"Great Basin covers about 200,000 sq mi","priority":2},
 {"id":"cross-ut-nv-wb","name":"Utah / Nevada line","kind":"crossing","lat":40.7178,"lon":-114.04,"legs":["ORD-SMF"],"tagline":"Into the Great Basin's heart","blurb":"The Utah-Nevada line runs near the western edge of the old Lake Bonneville basin.","lookFor":"Salt flats and desert ranges; on the westbound route, Wendover's casinos sit right on the line.","fact":"Line runs along about 114.04 W","priority":3},
 {"id":"cross-tz-mountain-pacific-wb","name":"Mountain to Pacific Time","kind":"crossing","lat":40.7109,"lon":-114.2,"legs":["ORD-SMF"],"tagline":"Another hour back","blurb":"West Wendover, Nevada, officially keeps Mountain Time to stay in step with Utah, so the time change falls just west of town rather than at the state line.","lookFor":"Desert ranges and salt flats around Wendover.","fact":"Clocks go back 1 hour westbound","priority":3},
 {"id":"cross-40th-parallel-wb","name":"40th Parallel Survey (Clarence King)","kind":"crossing","lat":40,"lon":-118.7168,"legs":["ORD-SMF"],"tagline":"The survey that mapped this corridor","blurb":"From 1867 to 1872 Clarence King led the U.S. Geological Exploration of the Fortieth Parallel, mapping a strip about 100 miles wide along the new transcontinental railroad route. His team mapped geology, mines and ancient lakes from the Sierra Nevada to the Rockies.","lookFor":"The 40th parallel itself passes beneath the route here, among Nevada's north-south desert ranges.","history":"In 1872 King exposed the Great Diamond Hoax, a field salted with gems in northwest Colorado. He became the first director of the U.S. Geological Survey in 1879.","fact":"Survey strip about 100 miles wide","priority":2},
 {"id":"cross-nv-ca-wb","name":"Nevada / California line","kind":"crossing","lat":39.59,"lon":-120,"legs":["ORD-SMF"],"tagline":"Into California","blurb":"North of Lake Tahoe the California-Nevada line follows the 120th meridian straight north to Oregon.","lookFor":"Forested Sierra slopes and the Truckee River valley near the line.","fact":"Follows the 120th meridian north of Lake Tahoe","priority":3},
 {"id":"cross-great-basin-rim-sierra-wb","name":"Great Basin rim (Sierra crest)","kind":"crossing","lat":39.44,"lon":-120.37,"legs":["ORD-SMF"],"tagline":"Back to rivers that reach the ocean","blurb":"At the Sierra crest, water flowing east goes to the Truckee River and dead-ends in Pyramid Lake. Water flowing west reaches the Yuba and Sacramento rivers and the Pacific.","lookFor":"Granite and forest at the crest north of Donner Pass, with Castle Peak just to the south.","fact":"Truckee River ends in Pyramid Lake, ~120 river miles","priority":2},
 {"id":"cross-great-basin-rim-sierra-eb","name":"Great Basin rim (Sierra crest)","kind":"crossing","lat":39.4692,"lon":-120.33,"legs":["SMF-ORD"],"tagline":"Leaving rivers that reach the ocean","blurb":"At the Sierra crest, water flowing west reaches the Pacific through the Yuba and Sacramento rivers. Water flowing east goes to the Truckee River and dead-ends in Pyramid Lake.","lookFor":"Granite ridges, small lakes and forest at the crest north of Donner Pass.","fact":"Great Basin covers about 200,000 sq mi","priority":2},
 {"id":"cross-nv-ca-eb","name":"California / Nevada line","kind":"crossing","lat":39.5599,"lon":-120,"legs":["SMF-ORD"],"tagline":"Into Nevada","blurb":"North of Lake Tahoe the California-Nevada line follows the 120th meridian straight north to Oregon.","lookFor":"Forested Sierra slopes and the Truckee River valley near the line.","fact":"Follows the 120th meridian north of Lake Tahoe","priority":3},
 {"id":"cross-40th-parallel-eb","name":"40th Parallel Survey (Clarence King)","kind":"crossing","lat":40,"lon":-118.51,"legs":["SMF-ORD"],"tagline":"The survey that mapped this corridor","blurb":"From 1867 to 1872 Clarence King led the U.S. Geological Exploration of the Fortieth Parallel, mapping a strip about 100 miles wide along the new transcontinental railroad route. His team mapped geology, mines and ancient lakes from the Sierra Nevada to the Rockies.","lookFor":"The 40th parallel itself passes beneath the route here, among Nevada's north-south desert ranges.","history":"In 1872 King exposed the Great Diamond Hoax, a field salted with gems in northwest Colorado. He became the first director of the U.S. Geological Survey in 1879.","fact":"Survey strip about 100 miles wide","priority":2},
 {"id":"cross-nv-ut-tz-eb","name":"Nevada / Utah line & Pacific to Mountain Time","kind":"crossing","lat":41.2887,"lon":-114.04,"legs":["SMF-ORD"],"tagline":"Into Utah, clocks forward an hour","blurb":"The Nevada-Utah line here is also the Pacific-Mountain time boundary. Ahead lies the Great Salt Lake Desert, the dry floor of Lake Bonneville.","lookFor":"Desert ranges giving way to pale salt and mud flats to the east.","fact":"Clocks go forward 1 hour eastbound","priority":2},
 {"id":"cross-ut-wy-eb","name":"Utah / Wyoming line","kind":"crossing","lat":41.809,"lon":-111.0465,"legs":["SMF-ORD"],"tagline":"Into Wyoming","blurb":"This part of the Wyoming-Utah line follows a parallel and a meridian drawn by surveyors, not any natural feature.","lookFor":"High sagebrush valleys near the Bear River, with Bear Lake to the north.","fact":"Wyoming's borders are all straight lines","priority":3},
 {"id":"cross-great-basin-rim-east-eb","name":"Great Basin rim (east)","kind":"crossing","lat":41.8813,"lon":-110.65,"legs":["SMF-ORD"],"tagline":"Rivers reach the sea again","blurb":"West of this divide, the Bear River and its creeks drain to Great Salt Lake and never reach the ocean. East of it, streams flow to the Green River, the Colorado and the Gulf of California.","lookFor":"Rolling ridges between the Bear River valley and the Hams Fork near Kemmerer.","fact":"Great Basin covers about 200,000 sq mi","priority":2},
 {"id":"cross-continental-divide-eb","name":"Continental Divide","kind":"crossing","lat":42.1853,"lon":-108.85,"legs":["SMF-ORD"],"tagline":"Atlantic on one side, Pacific on the other","blurb":"Near the Oregon Buttes, just south of South Pass, the Continental Divide splits in two to wrap around the Great Divide Basin. The eastbound track crosses the western branch here and passes near the northern rim of the basin before reaching Atlantic drainage.","lookFor":"The south tip of the Wind River Range to the north and the open Red Desert to the south.","fact":"South Pass, 7,412 ft, lies just north","priority":1},
 {"id":"cross-wy-ne-eb","name":"Wyoming / Nebraska line","kind":"crossing","lat":42.498,"lon":-104.053,"legs":["SMF-ORD"],"tagline":"Into Nebraska","blurb":"The Nebraska-Wyoming line follows a meridian surveyed across open high plains. Ground elevation here is about a mile above sea level.","lookFor":"Shortgrass prairie and wheat strips; the line itself is invisible except where roads jog.","fact":"Line runs along about 104.05 W","priority":3},
 {"id":"cross-tz-mountain-central-eb","name":"Mountain to Central Time","kind":"crossing","lat":42.5127,"lon":-101.05,"legs":["SMF-ORD"],"tagline":"Clocks forward an hour","blurb":"Cherry County, Nebraska, is so large that the time-zone line runs through it: the western part keeps Mountain Time and the east, including Valentine, keeps Central. The exact line follows precinct boundaries.","lookFor":"Rolling grass-covered Sandhills dotted with small lakes.","fact":"Cherry County is about 6,000 sq mi","priority":3},
 {"id":"cross-100th-eb","name":"100th meridian","kind":"crossing","lat":42.5007,"lon":-100,"legs":["SMF-ORD"],"tagline":"Where the arid West begins","blurb":"The 100th meridian roughly separates the humid East from the dry West. West of it, average rainfall drops below about 20 inches a year, too little for most crops without irrigation.","lookFor":"Notice more center-pivot circles, fewer trees and more open grassland to the west.","history":"John Wesley Powell argued in 1878 that land west of this line needed different laws for water and settlement.","fact":"About 20 inches of rain a year","priority":2},
 {"id":"cross-ne-ia-eb","name":"Nebraska / Iowa line near Sioux City","kind":"crossing","lat":42.5593,"lon":-96.5,"legs":["SMF-ORD"],"tagline":"Crossing the Missouri at the tri-state corner","blurb":"Near Sioux City the Missouri River separates Nebraska from South Dakota and Iowa, and the Big Sioux River joins it from the north to form the Iowa-South Dakota line.","lookFor":"A broad river valley with Sioux City on the east bank and the Loess Hills rising beyond it.","history":"Lewis and Clark passed here in August 1804.","fact":"Three states meet at the river confluence","priority":2},
 {"id":"cross-ia-il-eb","name":"Iowa / Illinois line (Mississippi River)","kind":"crossing","lat":42.2843,"lon":-90.43,"legs":["SMF-ORD"],"tagline":"Crossing the Mississippi","blurb":"The Mississippi River forms the Illinois-Iowa line. Its valley here is lined with limestone bluffs and backwater sloughs.","lookFor":"A broad river directly below, with wooded islands, backwaters and a lock and dam.","fact":"Drains about 40% of the lower 48 states","priority":2}
];
